    before=Database();assert len(before.properties)==5640 and len(before.states)==5373
    source='ivdre_2024_lpo_rigid_pur';url='https://www.ebi.ac.uk/europepmc/webservices/rest/PMC11013755/fullTextXML'
    def ev(locator,*roles):return [dict(source_id=source,url=url,locator=locator,supports=list(roles))]
    method='Section2.8 pycnometer paragraph, XML sec2dot8-polymers-16-00942; Table10 closed-cell row, PDFpp7/17 corroboration'
    def unknown(note):return dict(status='not_reported_in_inspected_source',text=None,evidence=ev(method,'condition'),notes=note)
