        state['state']['product_form']=dict(status='reported',text='Optimized rigid PUR foam specimens for source-reported closed-cell pycnometry; actual test-piece geometry not stated',evidence=ev('Sections2.7/2.8 optimized foam and pycnometer method','state'),notes='Do not transfer mold dimensions or water,compression,DMA or thermal-plate dimensions to these pieces.')
